  ["One more exchange this level"] = "Ein Tausch mehr in diesem Level", ["AMPLIFY"] = "VERSTÄRKEN", ["Buffs last 1 coin longer and get stronger"] = "Boni halten 1 Münze länger und werden stärker",
  ["ENDLESS"] = "ENDLOS", ["ENDLESS %d"] = "ENDLOS %d", ["LEVEL %d"] = "LEVEL %d", ["ENDLESS MODE"] = "ENDLOSMODUS", ["ENDLESS RUN OVER"] = "ENDLOSLAUF VORBEI",
  ["ENDLESS LEVELS CLEARED"] = "ENDLOS-LEVEL GESCHAFFT",
  ["INVERTED  -  EVERY %dTH FLIP"] = "UMGEDREHT  -  JEDER %d. WURF", ["COMBO +%d"] = "SERIE +%d", ["COMBO SHIELD"] = "SERIENSCHUTZ", ["Combo grows %d extra step"] = "Serie wächst um %d Schritt extra",
  ["The next combo break is prevented"] = "Der nächste Serienbruch wird verhindert", ["+%d POINTS  (x%.2f)"] = "+%d PUNKTE  (x%.2f)",
  ["COMBO"] = "SERIE", ["COMBO  %s x%d"] = "SERIE  %s x%d", ["SHIELD %d"] = "SCHUTZ %d", ["BUFF x%d  (%d LEFT)"] = "BONUS x%d  (%d ÜBRIG)", ["BUFF +%d%% HEADS  (%d LEFT)"] = "BONUS +%d %% KOPF  (%d ÜBRIG)",
  ["POT %dG"] = "POTT %dG", ["BANK %dG"] = "%dG SICHERN", ["BREAK LOSES POT"] = "SERIE BRICHT: TOPF WEG", ["PUSH"] = "WEITERZOCKEN",
  ["BUFF: NEXT COIN SWAPS SIDES"] = "BONUS: NÄCHSTE TAUSCHT SEITE", ["BUFF: NEXT COIN LANDS HEADS"] = "BONUS: NÄCHSTE LANDET AUF KOPF",
  ["HEADS %d%%  /  TAILS %d%%"] = "KOPF %d%%  /  ZAHL %d%%",
  ["HEADS %d%%  /  EDGE %d%%  /  TAILS %d%%"] = "KOPF %d%%  /  KANTE %d%%  /  ZAHL %d%%",
  ["EDGE"] = "KANTE", ["Tie"] = "Kante", ["EDGE %d%%"] = "KANTE %d%%",
  ["+%d PTS / QUOTA +%d"] = "+%d PKT / ZIEL +%d", ["  -  COSTS %d ENERGY"] = "  -  KOSTET %d ENERGIE",
  ["LOCKED  -  BUY IT IN THE SHOP TO UNLOCK"] = "GESPERRT  -  KAUFE SIE IM SHOP, UM SIE FREIZUSCHALTEN",
  -- how to play
  -- tutorial
  ["TUTORIAL"] = "TUTORIAL", ["SKIP"] = "ÜBERSPRINGEN", ["CLICK ANYWHERE TO CONTINUE"] = "KLICKE ZUM WEITERMACHEN",
  ["PRESS FLIP"] = "DRÜCKE WERFEN", ["PRESS NEXT COIN"] = "DRÜCKE NÄCHSTE MÜNZE",
  ["PRESS OPEN SHOP"] = "DRÜCKE SHOP ÖFFNEN", ["PRESS NEXT ROUND"] = "DRÜCKE NÄCHSTE RUNDE",
  ["THE GOAL"] = "DAS ZIEL",
  ["Each level has a QUOTA: points you must score before your coins run out. The bar fills as you score."] = "Jedes Level hat ein ZIEL: Punkte, die du erreichen musst, bevor deine Münzen ausgehen. Der Balken füllt sich mit deinen Punkten.",
  ["YOUR RESOURCES"] = "DEINE RESSOURCEN",
  ["Coins left in your stack, your gold, and your energy. Strong coins cost energy to flip."] = "Münzen im Stapel, dein Gold und deine Energie. Starke Münzen kosten Energie zum Werfen.",
  ["THE COIN BANK"] = "DIE MÜNZBANK",
  ["Your remaining coins stay visible in the bank. Click any coin to choose what to play next. Playing is free unless a coin shows an energy cost."] = "Deine übrigen Münzen bleiben vollständig sichtbar. Klicke eine Münze an, um sie als Nächstes zu spielen. Das Spielen ist kostenlos, außer eine Münze zeigt Energiekosten.",
  ["THE COIN IN PLAY"] = "DIE MÜNZE IM SPIEL",
  ["The coin with its Heads effect (blue, left) and Tails effect (red, right), and its odds below. Read them before you flip."] = "Die Münze mit ihrem Kopf-Effekt (blau, links), ihrem Zahl-Effekt (rot, rechts) und den Chancen darunter. Lies sie vor dem Werfen.",
  ["FLIP"] = "WERFEN", ["Press FLIP (or Space) to toss the coin."] = "Drücke WERFEN (oder Leertaste), um die Münze zu werfen.",
  ["THE RESULT"] = "DAS ERGEBNIS",
  ["The banner shows the side it landed on and the points you got. Press NEXT COIN to continue."] = "Das Banner zeigt die Seite und die Punkte, die du bekommen hast. Drücke NÄCHSTE MÜNZE zum Weitermachen.",
  ["FLIP AGAIN"] = "NOCHMAL WERFEN", ["Flip this one too. Two Heads in a row start a COMBO."] = "Wirf auch diese. Zweimal Kopf in Folge starten eine SERIE.",
  ["COMBO POT"] = "SERIEN-TOPF",
  ["Repeated results raise the combo multiplier and build an unbanked pot. BANK locks the pot and ends the combo."] = "Gleiche Ergebnisse erhöhen den Serienmultiplikator und füllen einen ungesicherten Topf. SICHERN behält den Topf und beendet die Serie.",
  ["PUSH flips the next coin to build your combo. If the streak breaks, you lose the unbanked pot."] = "WEITERZOCKEN wirft die nächste Münze und baut deine Serie aus. Bricht sie, verlierst du den ungesicherten Topf.",
  ["OPEN THE SHOP"] = "SHOP ÖFFNEN", ["Keep flipping for extra gold, or press OPEN SHOP to move on."] = "Wirf weiter für Extra-Gold oder drücke SHOP ÖFFNEN, um weiterzumachen.",
  ["THE SHOP"] = "DER SHOP",
  ["Between levels you buy COINS (larger and stronger decks raise the next quota), CHIPS (one-use helpers) and a PRIZE (lasts the run). REROLL refreshes the coins."] = "Zwischen den Leveln kaufst du MÜNZEN (größere und stärkere Decks erhöhen das nächste Ziel), CHIPS (Einweg-Helfer) und eine PRÄMIE (hält den ganzen Lauf). NEU WÜRFELN erneuert die Münzen.",
  ["Select a coin below to remove it from the deck for 8 gold."] = "Wähle unten eine Münze, um sie für 8 Gold aus dem Deck zu entfernen.",
  ["YOUR DECK"] = "DEIN DECK", ["Your coins. Click one to select it for removal. The dark slots on the right are extra deck slots: 5 gold, 2 more for each one you buy, up to ten."] = "Deine Münzen. Klicke eine an, um sie zum Entfernen auszuwählen. Die dunklen Plätze rechts sind zusätzliche Deckplätze: 5 Gold, für jeden gekauften 2 mehr, bis zu zehn.",
  ["NEXT ROUND"] = "NÄCHSTE RUNDE", ["Press the red button when you are ready for the next level."] = "Drücke den roten Knopf, wenn du für das nächste Level bereit bist.",
  ["CHIPS"] = "CHIPS", ["CHIPS appear here. They are one-use helpers from the shop. Click one while a coin is ready to flip; an Energy Drink gives 2 energy. You can carry up to three."] = "Hier erscheinen CHIPS. Sie sind Einweg-Helfer aus dem Shop. Klicke einen an, wenn eine Münze zum Werfen bereit ist; ein Energydrink gibt 2 Energie. Du kannst bis zu drei mitnehmen.",
  ["A NEW MODIFIER"] = "EIN NEUER MODIFIKATOR", ["From level 2 on, every level has a MODIFIER: a bonus or a twist for this level only. Read it here before you flip."] = "Ab Level 2 hat jedes Level einen MODIFIKATOR: einen Bonus oder eine Besonderheit nur für dieses Level. Lies ihn hier, bevor du wirfst.",
  ["RUNNING OUT OF COINS"] = "MÜNZEN GEHEN AUS", ["Watch the coin count at the top. If the stack empties before the quota is met, the Out of Coins prompt lets you BANK any combo pot or BUY MORE COINS to return 3 played coins for gold. Exchanges are limited each level; without one, the level ends."] = "Achte oben auf die Münzanzahl. Ist der Stapel leer, bevor das Ziel erreicht ist, kannst du im Fenster KEINE MÜNZEN MEHR einen Serien-Topf sichern oder MEHR MÜNZEN KAUFEN, um 3 gespielte Münzen gegen Gold zurückzuholen. Pro Level gibt es nur begrenzt Tausche; sonst endet das Level.",
  ["THAT'S IT"] = "DAS WAR'S",
  ["Beat eight levels ending with The House. An Encounter shapes the run; choose Augments before levels 3 and 6 to improve your bank or playstyle. Win to unlock the next character."] = "Schlage acht Level bis zum Haus. Eine Begegnung prägt den Lauf; wähle vor Level 3 und 6 Verstärkungen für deine Münzbank oder Spielweise. Gewinne, um den nächsten Charakter freizuschalten.",

  -- how to play
  ["THE GOAL"] = "DAS ZIEL",
  ["Beat the quota before your coins run out. Bad flips can raise it. A run has eight levels: one Encounter changes the run, and Augments appear before levels 3 and 6. The House is the final level."] =
    "Erreiche das Ziel, bevor dir die Münzen ausgehen. Schlechte Würfe können es erhöhen. Ein Lauf hat acht Level: Eine Begegnung verändert den Lauf, und vor Level 3 und 6 erscheinen Verstärkungen. Das Haus ist das letzte Level.",
  ["YOUR COINS"] = "DEINE MÜNZEN",
  ["You play with a small stack of coins. Each coin has a Heads chance and a Heads and a Tails effect. Every coin is played once per level; nothing is reshuffled."] =
    "Du spielst mit einem kleinen Stapel Münzen. Jede Münze hat eine Kopf-Chance sowie einen Kopf- und einen Zahl-Effekt. Jede Münze wird pro Level einmal gespielt; nichts wird neu gemischt.",
  ["EACH LEVEL"] = "JEDES LEVEL",
  ["The entire remaining coin bank stays visible. Click any coin to choose what to play next; choosing is free. Coins with an energy cost spend it when flipped."] =
    "Deine übrigen Münzen bleiben vollständig in der Bank sichtbar. Klicke eine beliebige Münze an, um sie als Nächstes zu spielen. Die Auswahl ist kostenlos; Energiekosten fallen erst beim Werfen an.",
  ["ENERGY"] = "ENERGIE",
  ["Strong coins cost ENERGY to flip (shown as E1, E2). You get 3 per level; Spark, Copper and Flux Capacitor give more. If you cannot pay, choose a different coin. Your last coin can still flip for up to 2 gold."] =
    "Starke Münzen kosten ENERGIE zum Werfen (angezeigt als E1, E2). Du bekommst 3 pro Level; Funke, Kupfer und Flux-Kondensator geben mehr. Wenn du nicht genug Energie hast, wähle eine andere Münze. Deine letzte Münze kannst du für bis zu 2 Gold trotzdem werfen.",
  ["QUOTA MET"] = "ZIEL ERREICHT",
  ["You are paid gold at once and the level stays open: every 2 extra points pay 1 more gold. Press OPEN SHOP (top right) when you want to move on."] =
    "Du wirst sofort mit Gold bezahlt und das Level bleibt offen: Je 2 Extrapunkte zahlen 1 weiteres Gold. Drücke SHOP ÖFFNEN (oben rechts), wenn du weiter willst.",
  ["If the quota is not met, pay gold to EXCHANGE: 3 of your played coins come back (only a limited number of times per level). If you cannot, the run is over."] =
    "Wenn das Ziel nicht erreicht ist, zahle Gold zum TAUSCHEN: 3 deiner gespielten Münzen kommen zurück (pro Level nur begrenzt oft). Wenn du das nicht kannst, ist der Lauf vorbei.",
  ["THE SHOP"] = "DER SHOP",
  ["Buy COINS (larger and stronger decks raise the next quota), CHIPS (one-use helpers, used mid-level), and a PRIZE (lasts the run). Odds Tuner adds Heads chance; Coin Removal drops a weak coin."] =
    "Kaufe MÜNZEN (größere und stärkere Decks erhöhen das nächste Ziel), CHIPS (Einweg-Helfer, im Level benutzbar) und eine PRÄMIE (hält den ganzen Lauf). Der Chancen-Tuner erhöht die Kopf-Chance; die Münz-Entfernung wirft eine schwache Münze raus.",
  ["CONTROLS"] = "STEUERUNG",
  ["Space = Flip / Next Coin.  Click = select a coin.  Esc = menu (your run waits).  Hover a coin for details. The run is saved at each level start and in the shop; Continue resumes it, a level in progress restarts."] =
    "Leertaste = Werfen / Nächste Münze.  Klick = Münze auswählen.  Esc = Menü (dein Lauf wartet).  Fahre über eine Münze für Details. Der Lauf wird zu Beginn jedes Levels und im Shop gespeichert; Weiter setzt ihn fort, ein laufendes Level beginnt neu.",
  ["GOT IT"] = "VERSTANDEN",

